package org.eclipse.rdf4j.sail.lmdb;

import java.util.Optional;
import java.util.Set;

import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.sail.lmdb.config.FrontierEstimatorMode;
import org.eclipse.rdf4j.sail.lmdb.estimation.RowEvidence;
import org.eclipse.rdf4j.sail.lmdb.frontier.FrontierFallbackReason;
import org.eclipse.rdf4j.sail.lmdb.frontier.FrontierLeafEstimate;
import org.eclipse.rdf4j.sail.lmdb.frontier.FrontierStatisticsAvailability;
import org.eclipse.rdf4j.sail.lmdb.frontier.FrontierStatisticsStatus;
import org.eclipse.rdf4j.sail.lmdb.frontier.LmdbStatisticsService;

/**
 * The single predicate for "Frontier Statistics V2 answered this leaf probe authoritatively" and the storage fallback
 * evidence used whenever it did not.
 * <p>
 * Frontier owns leaf evidence only in {@link FrontierEstimatorMode#AUTHORITATIVE} mode, with a
 * {@link FrontierFallbackReason#NONE} answer and a finite point estimate. Every other outcome (OFF, SHADOW observation,
 * no generation yet, stale generation, cleared mutation tail, memory pressure) hands planning back to the bounded
 * storage chain: the B-tree page summary, the exact count on the decision tier, and finally the total-rows ceiling.
 * Unknown cardinality therefore never collapses to a one-row guess while storage evidence exists.
 */
final class LmdbFrontierLeafAnswer {

	static final String STORAGE_SUMMARY_SOURCE = "lmdb-storage-summary";
	static final String UNKNOWN_CEILING_SOURCE = "lmdb-unknown-ceiling";
	private static final double STORAGE_SUMMARY_CONFIDENCE = 0.55d;

	private LmdbFrontierLeafAnswer() {
	}

	/** {@code true} only when Frontier may own planning evidence for the probed leaf. */
	static boolean answered(FrontierEstimatorMode mode, FrontierLeafEstimate estimate) {
		return mode == FrontierEstimatorMode.AUTHORITATIVE && estimate != null
				&& estimate.fallbackReason() == FrontierFallbackReason.NONE && valid(estimate.pointRows());
	}

	static boolean valid(double rows) {
		return Double.isFinite(rows) && rows >= 0.0d;
	}

	/**
	 * {@code true} only when an authoritative Frontier service currently owns planning as a whole: a READY generation
	 * that covers the journal. Cheaper than a leaf probe; used by paths that have no leaf estimate at hand (distinct
	 * cursor-skip costing). OFF, SHADOW, a missing generation and every stale or uncovered state hand the bounded
	 * storage probes back to the planner, exactly as OFF mode does.
	 */
	static boolean ready(FrontierEstimatorMode mode, LmdbStatisticsService statistics) {
		if (mode != FrontierEstimatorMode.AUTHORITATIVE || statistics == null) {
			return false;
		}
		FrontierStatisticsStatus status = statistics.status();
		return status != null && status.availability() == FrontierStatisticsAvailability.READY
				&& status.fallbackReason() == FrontierFallbackReason.NONE;
	}

	/**
	 * Roadmap fallback chain once Frontier did not answer: the bounded B-tree page summary first, then the total-rows
	 * ceiling when the summary itself is unavailable. Empty only when storage cannot answer either question.
	 */
	static Optional<EstimateCandidate> storageFallback(LmdbStatementPatternCardinalitySource cardinalities,
			FrontierEstimatorMode mode, FrontierLeafEstimate frontier, StatementPattern pattern,
			EstimateContext context) {
		double rows = cardinalities.estimateForPlanning(pattern);
		if (valid(rows)) {
			RowEvidence summary = storageSummaryEvidence(rows, context, storageSummarySource(mode, frontier));
			return Optional.of(EstimateCandidate.of(pattern, rows, summary, EstimateCandidate.Kind.STORAGE_SUMMARY,
					null, Set.of()));
		}
		double ceiling = cardinalities.estimateForPlanning(totalRowsPattern());
		if (valid(ceiling)) {
			return Optional.of(EstimateCandidate.of(pattern, ceiling, ceilingEvidence(ceiling, context),
					EstimateCandidate.Kind.HEURISTIC, null, Set.of()));
		}
		return Optional.empty();
	}

	/** Storage-summary source, suffixed with the Frontier fallback reason when an authoritative service declined. */
	private static String storageSummarySource(FrontierEstimatorMode mode, FrontierLeafEstimate estimate) {
		if (mode != FrontierEstimatorMode.AUTHORITATIVE || estimate == null
				|| estimate.fallbackReason() == FrontierFallbackReason.NONE) {
			return STORAGE_SUMMARY_SOURCE;
		}
		return STORAGE_SUMMARY_SOURCE + "/frontier-" + estimate.fallbackReason().name();
	}

	/** Bounded B-tree page estimate: interval [rows / 2, 2 * rows]. */
	private static RowEvidence storageSummaryEvidence(double rows, EstimateContext context, String source) {
		double upper = rows == 0.0d ? 1.0d : Math.max(rows, rows * 2.0d);
		return new RowEvidence(rows, Math.max(0.0d, rows * 0.5d), upper, STORAGE_SUMMARY_CONFIDENCE, false,
				context.snapshotIdentity(), context.snapshotVersion(), source);
	}

	/** Pessimistic ceiling: the pattern cannot produce more rows than the store holds. */
	private static RowEvidence ceilingEvidence(double totalRows, EstimateContext context) {
		return new RowEvidence(totalRows, 0.0d, totalRows, 0.0d, false, context.snapshotIdentity(),
				context.snapshotVersion(), UNKNOWN_CEILING_SOURCE);
	}

	private static StatementPattern totalRowsPattern() {
		return new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o"));
	}
}
